"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[31549],{74169:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ToolGripService","desc":"Fixes the `RightGrip` of every Tool a player holds:\\n- Moves `C0` (the hand\'s `RightGripAttachment`) to where it is on the block\\n  R15 rig. Avatar bundles move that attachment, so without this the weapon\\n  sits off the pose the hold animations were made for.\\n- If the Tool has moving parts (a Motor6D under its `Handle`), turns the\\n  Weld into a Motor6D with the same C0/C1. The Animator only reaches a\\n  joint through a chain of Motor6Ds from the character, so this lets the\\n  Fire / Reload animations (`WeaponAnims`) move the weapon parts.","realm":["Server"],"source":{"line":15,"path":"src/ServerScriptService/ToolGripService.server.luau"}}')}}]);